// TestQA_SpecDTOAccuracy decodes the served /openapi.json and asserts each
// handler DTO's property names are present in the spec (R-3 DTO drift catcher),
// and that the R-01 collapse is reflected: api.libraryResponse is gone and POST
// /libraries 201 refs api.libraryDTO.
func TestQA_SpecDTOAccuracy(t *testing.T) {
	rec := httptest.NewRecorder()
	Handler(nil, Options{}).ServeHTTP(rec, httptest.NewRequest(http.MethodGet, "/openapi.json", nil))
	if rec.Code != http.StatusOK {
		t.Fatalf("/openapi.json status = %d, want 200", rec.Code)
	}
	var spec map[string]any
	if err := json.Unmarshal(rec.Body.Bytes(), &spec); err != nil {
		t.Fatalf("decode openapi.json: %v", err)
	}
	defs, _ := spec["definitions"].(map[string]any)

	hasProps := func(defName string, want ...string) {
		t.Helper()
		d, ok := defs[defName].(map[string]any)
		if !ok {
			t.Fatalf("spec has no definition %q (R-3 drift)", defName)
		}
		props, _ := d["properties"].(map[string]any)
		for _, w := range want {
			if _, ok := props[w]; !ok {
				t.Errorf("definition %q missing property %q (R-3 DTO drift)", defName, w)
			}
		}
	}

	// Handler DTO property names must match the spec (catches annotation drift).
	hasProps("api.createLibraryRequest", "module_id", "root_path", "display_name")
	hasProps("api.itemDTO", "id", "document", "media_type", "status")
	hasProps("api.libraryDTO", "id", "module_id", "root_path", "display_name")
	hasProps("api.statusResponse", "plugins", "enrich")
	hasProps("api.scanResponse", "library_id", "discovered", "persisted")

	// R-01 collapse landed in the spec: the duplicate api.libraryResponse
	// definition is GONE (one library wire type, not two).
	if _, stillPresent := defs["api.libraryResponse"]; stillPresent {
		t.Errorf("api.libraryResponse still in spec — R-01 collapse did not land (duplicate wire type)")
	}

	// POST /libraries 201 response now refs the single api.libraryDTO.
	paths, _ := spec["paths"].(map[string]any)
	libs, _ := paths["/libraries"].(map[string]any)
	post, _ := libs["post"].(map[string]any)
	responses, _ := post["responses"].(map[string]any)
	created, _ := responses["201"].(map[string]any)
	schema, _ := created["schema"].(map[string]any)
	ref, _ := schema["$ref"].(string)
	if ref != "#/definitions/api.libraryDTO" {
		t.Errorf("POST /libraries 201 $ref = %q, want #/definitions/api.libraryDTO (R-01 collapse)", ref)
	}
}

// TestQA_ServedEqualsCommitted asserts the served /openapi.yaml is byte-identical
// to the committed embedded file — the serve path is a pure embed passthrough
// (catches any runtime mutation). Reads the on-disk committed bytes the embed
// directive compiles in (test cwd = internal/web, so the path is api/openapi.yaml).
func TestQA_ServedEqualsCommitted(t *testing.T) {
	rec := httptest.NewRecorder()
	Handler(nil, Options{}).ServeHTTP(rec, httptest.NewRequest(http.MethodGet, "/openapi.yaml", nil))
	if rec.Code != http.StatusOK {
		t.Fatalf("/openapi.yaml status = %d, want 200", rec.Code)
	}
	disk, err := os.ReadFile("api/openapi.yaml")
	if err != nil {
		t.Fatalf("read committed api/openapi.yaml: %v (test cwd must be internal/web)", err)
	}
	if !bytes.Equal(disk, rec.Body.Bytes()) {
		t.Errorf("served /openapi.yaml != committed api/openapi.yaml (serve path mutated bytes); served %d bytes, committed %d bytes",
			rec.Body.Len(), len(disk))
	}
}
